const raw = $json.body.vitalkontrolle_log;

const result = raw
  .split(/\r?\n/)
  .slice(2)
  .map(line => line.trim())
  .filter(line => line.length > 0)
  .map(line => {
    const [standort, datum10, zeit10, datum14, zeit14] = line.split(/\s+/);
    return {
      standort,
      kontrolle_10: `${datum10} ${zeit10}`,
      kontrolle_14: `${datum14} ${zeit14}`
    };
  });

const now = $now.setZone('Europe/Berlin');
const heute = now.toFormat('dd.MM.yyyy');
const nachmittag = now.hour >= 13;

const feld  = nachmittag ? 'kontrolle_14' : 'kontrolle_10';
const label = nachmittag ? '14 Uhr' : '10 Uhr';

const fehlend = result
  .filter(r => !String(r[feld] ?? '').startsWith(heute))
  .map(r => r.standort);

const ok = fehlend.length === 0;

const status = ok
  ? `✅ Vitalkontrolle ${label} ist gelaufen`
  : `🚨 Vitalkontrolle ${label} ist NICHT gelaufen bei: ${fehlend.join(', ')}`;

const tabelle = result
  .map(r => `${r.standort}  ${r[feld]}`)
  .join('\n');

const text = `${status}\n\n<pre>${tabelle}</pre>`;

return [{ json: { text, ok, geprueft: label, fehlend, vitalkontrolle_structured: result } }];

